hooks.command:
projmem session "$CLAUDE_TOOL_FILE_PATH" --max-notes 3 --json 2>/dev/null | python3 -c 'import sys,json
try:
    d=json.load(sys.stdin)
except Exception:
    sys.exit(0)
rm=d.get("repo_memory") or {}
notes=d.get("notes") or {}
n=notes.get("note_count",0)
c=rm.get("contradicted_count",0)
if n or c:
    print(f"projmem: {n} note(s) on this target, contradicted_count={c}. Run projmem session <target> before editing.")' 2>/dev/null || true
